import{_ as t,o as e,c as i,a2 as s}from"./chunks/framework.CjPXnAcb.js";const h=JSON.parse('{"title":"踩坑记录","description":"","frontmatter":{"title":"踩坑记录"},"headers":[],"relativePath":"pitfalls/index.md","filePath":"pitfalls/index.md","lastUpdated":1789060104000}'),r={name:"pitfalls/index.md"};function l(n,o,a,g,c,d){return e(),i("div",null,[...o[0]||(o[0]=[s('<h1 id="踩坑记录" tabindex="-1">踩坑记录 <a class="header-anchor" href="#踩坑记录" aria-label="Permalink to &quot;踩坑记录&quot;">​</a></h1><blockquote><p>报错不是失败，是游戏读档点。规矩：每条记录都要写全「现象 → 当时在干什么 → 原因（大白话）→ 怎么解决 → 学到什么」。报错原文尽量原样贴，将来搜索时能对上。</p></blockquote><h2 id="_001-git-不是内部或外部命令" tabindex="-1">#001 <code>&#39;git&#39; 不是内部或外部命令</code> <a class="header-anchor" href="#_001-git-不是内部或外部命令" aria-label="Permalink to &quot;#001 `&#39;git&#39; 不是内部或外部命令`&quot;">​</a></h2><ul><li><p><strong>现象</strong>：在 cmd 里敲 <code>git --version</code>，返回：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&#39;git&#39; 不是内部或外部命令，也不是可运行的程序或批处理文件。</span></span></code></pre></div></li><li><p><strong>当时在干什么</strong>：检查电脑环境，确认 Git 装没装。</p></li><li><p><strong>原因（大白话）</strong>：cmd 接到一个命令名后，会按 <strong>PATH</strong>（环境变量里的「地址簿」）挨个文件夹找同名程序；地址簿里没有 git 所在的文件夹，就报这条错。<strong>这条错只说明「找不到」，不代表「没装」</strong>——当时 git 其实就躺在另一个项目的 <code>_tools\\cmd</code> 里，只是那个文件夹不在地址簿上。</p></li><li><p><strong>怎么解决</strong>：要么把程序所在文件夹加进 PATH，要么像我一样直接用完整路径调用（<code>&quot;C:\\...\\_tools\\cmd\\git.exe&quot; --version</code>）。</p></li><li><p><strong>学到什么</strong>：见到「不是内部或外部命令」，第一反应应该是「查地址簿」，而不是「软件坏了」。详见<a href="/my-wiki/prereq/01-command-line.html">前置知识 01 · 命令行</a>。</p></li></ul><h2 id="_002-git-明明没装-gitconfig-却存在" tabindex="-1">#002 Git 明明没装，<code>.gitconfig</code> 却存在 <a class="header-anchor" href="#_002-git-明明没装-gitconfig-却存在" aria-label="Permalink to &quot;#002 Git 明明没装，`.gitconfig` 却存在&quot;">​</a></h2><ul><li><strong>现象</strong>：<code>git</code> 命令跑不了，但 <code>C:\\Users\\王奕博\\.gitconfig</code> 文件实实在在存在，里面还写着 GitHub 用户名。</li><li><strong>当时在干什么</strong>：环境检查时发现 Git 报「找不到」，顺手查了用户主目录。</li><li><strong>原因（大白话）</strong>：<code>.gitconfig</code> 是 Git 的<strong>配置文件</strong>，程序和配置是两回事——之前的会话用便携版 Git 干过活、写过配置，后来环境变量里找不到程序了，配置文件却留了下来。就像搬走了钢琴，琴谱还留在墙上。</li><li><strong>怎么解决</strong>：不用删。找到（或重新装）Git 后，这些配置（用户名、邮箱、凭据助手）自动生效。</li><li><strong>学到什么</strong>：报错说「程序找不到」≠「一切从零开始」。排查环境时，配置文件、安装目录、PATH 要分开看。</li></ul><h2 id="_003-powershell-脚本里的中文路径变乱码" tabindex="-1">#003 PowerShell 脚本里的中文路径变乱码 <a class="header-anchor" href="#_003-powershell-脚本里的中文路径变乱码" aria-label="Permalink to &quot;#003 PowerShell 脚本里的中文路径变乱码&quot;">​</a></h2><ul><li><strong>现象</strong>：执行 <code>.ps1</code> 安装脚本，报「对路径『涓汉椤圭洰Wiki缃戠珯』的访问被拒绝」——好好一个「个人项目Wiki网站」变成了一串天书。</li><li><strong>当时在干什么</strong>：跑自动下载 Node.js 的 PowerShell 脚本，脚本里写死了中文路径。</li><li><strong>原因（大白话）</strong>：<strong>编码问题</strong>。Windows 自带的 PowerShell 5.1 读「无 BOM 的 UTF-8」脚本时，会按系统默认的 GBK 编码去解——中文每个字被错误拆分，全变乱码，路径自然不存在。</li><li><strong>怎么解决</strong>：脚本里<strong>只用 ASCII 字符</strong>：不写死中文路径，改用 <code>$PSScriptRoot</code>（脚本自己所在的文件夹）来定位；或者保存成「带 BOM 的 UTF-8」。</li><li><strong>学到什么</strong>：写自动化脚本，路径、文件名尽量用英文；中文不是不能用，但要理解编码这层「翻译」。这也是为什么项目文件夹最好起英文名。</li></ul><h2 id="_004-github-的-token-权限不够-缺-workflow-scope" tabindex="-1">#004 GitHub 的 token 权限不够（缺 workflow scope） <a class="header-anchor" href="#_004-github-的-token-权限不够-缺-workflow-scope" aria-label="Permalink to &quot;#004 GitHub 的 token 权限不够（缺 workflow scope）&quot;">​</a></h2><ul><li><strong>现象</strong>：用 gh CLI 登录 GitHub 没问题，但把 <code>.github/workflows/deploy.yml</code> 推上去时会被拒绝（ refusing to allow ... create or update workflow）。</li><li><strong>当时在干什么</strong>：首次推送仓库，其中包含自动部署的工作流文件。</li><li><strong>原因（大白话）</strong>：GitHub 的 <strong>token</strong>（令牌）像一张<strong>门禁卡</strong>，每张卡上刻着能开哪些门（叫 <strong>scope</strong>，权限范围）。当时的卡有 <code>repo</code>（读写仓库）权限，但没有 <code>workflow</code>（创建/修改自动化工作流）权限——这是防止偷卡的人偷偷改你的自动化流水线。</li><li><strong>怎么解决</strong>：给卡加权限：<code>gh auth refresh -s workflow</code>，它会给你一个一次性代码，去浏览器 <code>github.com/login/device</code> 输入并授权即可（浏览器里已登录 GitHub 的话就是点两下）。</li><li><strong>学到什么</strong>：token = 门禁卡，scope = 卡上刻的门。权限报错先看「卡上刻了什么」，而不是急着重新登录。</li></ul><div class="warning custom-block"><p class="custom-block-title">状态备注（2026-09-11 凌晨）</p><p>本次授权<strong>还没完成</strong>——导师生成了授权码，但输码需要学员本人在浏览器点两下，只能等醒来操作。所以目前 <code>.github/workflows/deploy.yml</code> 还躺在本地没进仓库，网站先用「gh-pages 分支」方式手动部署（这个方式不需要 workflow 权限）。授权完成后即可切回全自动的 Actions 部署。</p></div><h2 id="_005-国内网络装依赖慢-失败-→-用镜像" tabindex="-1">#005 国内网络装依赖慢/失败 → 用镜像 <a class="header-anchor" href="#_005-国内网络装依赖慢-失败-→-用镜像" aria-label="Permalink to &quot;#005 国内网络装依赖慢/失败 → 用镜像&quot;">​</a></h2><ul><li><strong>现象</strong>：<code>npm install</code> / <code>pip install</code> 龟速甚至超时断开。</li><li><strong>当时在干什么</strong>：安装 VitePress 依赖、下载 Node.js 安装包。</li><li><strong>原因（大白话）</strong>：官方仓库的服务器大多在国外，链路又远又挤。</li><li><strong>怎么解决</strong>：换国内<strong>镜像</strong>（官方仓库的国内分店）： <ul><li>npm：本项目已配 <code>.npmrc</code> 指向 <code>https://registry.npmmirror.com/</code></li><li>pip：<code>py -m pip install 包名 -i https://pypi.tuna.tsinghua.edu.cn/simple</code></li><li>Node.js 安装包：<code>https://registry.npmmirror.com/-/binary/node/</code></li></ul></li><li><strong>学到什么</strong>：下载慢先想「哪里有分店」，别傻等。详见<a href="/my-wiki/prereq/02-node-and-npm.html">前置知识 02</a> 与 <a href="/my-wiki/prereq/06-python-env.html">06</a>。</li></ul><h2 id="_006-预防篇-部署后整站白屏-样式全丢" tabindex="-1">#006（预防篇）部署后整站白屏/样式全丢 <a class="header-anchor" href="#_006-预防篇-部署后整站白屏-样式全丢" aria-label="Permalink to &quot;#006（预防篇）部署后整站白屏/样式全丢&quot;">​</a></h2><ul><li><strong>现象</strong>：本地预览一切正常，部署到 GitHub Pages 后打开是白屏，浏览器控制台一堆 404。</li><li><strong>为什么提前记</strong>：这是 VitePress + GitHub Pages 的<strong>经典第一坑</strong>，本站配置时已提前规避，记下来防将来复发。</li><li><strong>原因（大白话）</strong>：GitHub Pages 把站点挂在 <code>https://用户名.github.io/my-wiki/</code> 这种<strong>子路径</strong>下，而 VitePress 默认按「根路径」生成链接（比如去找 <code>/assets/xxx.js</code>），实际上文件在 <code>/my-wiki/assets/xxx.js</code>——所有资源都 404，样式脚本全加载不到。</li><li><strong>怎么解决</strong>：在 <code>docs/.vitepress/config.mjs</code> 里写 <code>base: &#39;/my-wiki/&#39;</code>（仓库名是什么就写什么）。本站配置里那一行就是干这个的。</li><li><strong>学到什么</strong>：「本地好的，线上一塌糊涂」先想路径差异：根路径 vs 子路径。</li></ul>',15)])])}const u=t(r,[["render",l]]);export{h as __pageData,u as default};
